&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Ensure customer satisfaction.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;~25% travel.&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
